using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using RogControl;

public static class ReceiverGuiTests {
 static int checks;static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool yes,string message){checks++;if(!yes)throw new Exception(message);}
 static Dictionary<string,object> Map(params object[] pairs){var result=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)result[(string)pairs[i]]=pairs[i+1];return result;}
 static object Field(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static object Invoke(MainWindow window,string name,params object[] values){return typeof(MainWindow).GetMethod(name,Hidden).Invoke(window,values);}
 static IEnumerable<DependencyObject> Walk(DependencyObject node){yield return node;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(node,i)))yield return child;}
 static FrameworkElement Layout(MainWindow window,int width){Invoke(window,"ShowPage","device:receiver");var root=(FrameworkElement)window.Content;root.Measure(new Size(width,826));root.Arrange(new Rect(0,0,width,826));root.UpdateLayout();return root;}
 [STAThread]public static int Main(){try{Run();return 0;}catch(Exception error){Console.WriteLine(error.GetType().Name+": "+error.Message);return 1;}}
 static void Run(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new MainWindow(true);var states=(List<Dictionary<string,object>>)Field(window,"receiverStates");var state=Map("deviceId","synthetic-receiver","pid",6862,"online",true,"readbackConfirmed",true,"snapshot",Map("firmware","1.2.3","pairedDevices",new object[]{Map("kind","keyboard","model","Synthetic keyboard")}));states.Add(state);
  foreach(int width in new[]{1180,1538,2560}){var root=Layout(window,width);var labels=Walk(root).OfType<TextBlock>().Select(t=>t.Text).ToArray();Check(labels.Contains("Synthetic keyboard")&&labels.Contains("无设备"),"Confirmed pair and confirmed empty slot are separate");Check(labels.Contains("已配对设备")&&labels.Contains("新增配对设备"),"Both original pairing areas remain visible");Check(!Walk(root).OfType<Image>().Any(),"Pairing page does not introduce a product-photo column");foreach(var button in Walk(root).OfType<Button>().Where(b=>new[]{"重置与配对","检查更新","↻"}.Contains(Convert.ToString(b.Content)))){Check(!button.IsEnabled,"Unshown test cannot query or modify receiver state");button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}var scroll=Walk(root).OfType<ScrollViewer>().First(s=>s.Content is StackPanel&&((StackPanel)s.Content).Width==920);scroll.ScrollToRightEnd();root.UpdateLayout();Check(width==1180?scroll.ScrollableWidth>0&&Math.Abs(scroll.HorizontalOffset-scroll.ScrollableWidth)<1:scroll.ScrollableWidth==0,"Receiver canvas is reachable at the inspected sizes");Check(!window.IsVisible&&new System.Windows.Interop.WindowInteropHelper(window).Handle==IntPtr.Zero,"No native window is created");}
  ((Dictionary<string,object>)state["snapshot"])["pairedDevices"]=new object[]{Map("kind","unknown","model","Unknown paired device")};Check(!Walk(Layout(window,1538)).OfType<TextBlock>().Any(t=>t.Text=="无设备"),"An unknown paired model cannot be called an empty slot");((Dictionary<string,object>)state["snapshot"])["pairedDevices"]=new object[]{Map("kind","keyboard","model","Synthetic keyboard")};state["online"]=false;var offlineLabels=Walk(Layout(window,1538)).OfType<TextBlock>().Select(t=>t.Text).ToArray();Check(!offlineLabels.Contains("Synthetic keyboard")&&!offlineLabels.Contains("无设备"),"Offline pair cache is unknown rather than a current empty slot");state["online"]=true;state["readbackConfirmed"]=false;Check(!Walk(Layout(window,1538)).OfType<TextBlock>().Any(t=>t.Text=="Synthetic keyboard"),"Unconfirmed paired data remains unknown");state["readbackConfirmed"]=true;Set(window,"receiverTab","固件更新");Check(Walk(Layout(window,1538)).OfType<TextBlock>().Any(t=>t.Text=="当前固件版本：1.2.3"),"Firmware tab shows only the confirmed observed version");state["online"]=false;Check(Walk(Layout(window,1538)).OfType<TextBlock>().Any(t=>t.Text=="当前固件版本：—"),"Offline firmware is not shown as current");state["online"]=true;states.Add(Map("deviceId","synthetic-speednova","pid",6864,"online",true,"readbackConfirmed",true,"product","Synthetic SpeedNova","snapshot",Map("firmware","2.3.4","pairedDevices",new object[0])));Set(window,"selectedReceiverId","synthetic-speednova");Check(Walk(Layout(window,1538)).OfType<TextBlock>().Any(t=>t.Text=="ROG SPEEDNOVA 8K RECEIVER"),"Existing multiple-receiver support is retained");Check(Walk(Layout(window,1538)).OfType<ComboBox>().Any(c=>c.Items.Count==2&&!c.IsEnabled),"Selecting a receiver is local and guarded in render mode");var worker=(WorkerClient)Field(window,"gearWorker");Check(typeof(WorkerClient).GetField("process",Hidden).GetValue(worker)==null,"Tests never start a device worker");Console.WriteLine("PASS "+checks+" receiver GUI checks; HWNDs=0; workers=0; pairing/reset/firmware writes=0.");app.Shutdown();}
}
